const results = await Promise.allSettled([
  tools.exec_command({cmd:"find . -name AGENTS.md -o -name checkpoint.md | head -80",workdir:"/app",yield_time_ms:10000,max_output_tokens:2000}),
  tools.exec_command({cmd:"git status --short && ls",workdir:"/app",yield_time_ms:10000,max_output_tokens:2000}),
  tools.exec_command({cmd:"find . -path '*reversetunnel*' | head -100",workdir:"/app",yield_time_ms:10000,max_output_tokens:4000})
]); results.forEach((r,i)=>text(JSON.stringify({i,result:r.status==="fulfilled"?r.value.output:String(r.reason)})));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"grep -RIn --include='*.go' -E 'newlocalSite|localSites|localSite|requireLocalAgentForConn|upsertServiceConn' lib/reversetunnel | head -220",workdir:"/app",yield_time_ms:10000,max_output_tokens:12000}),
  tools.exec_command({cmd:"sed -n '1,260p' lib/reversetunnel/localsite.go",workdir:"/app",yield_time_ms:10000,max_output_tokens:12000}),
  tools.exec_command({cmd:"sed -n '1,300p' lib/reversetunnel/srv.go",workdir:"/app",yield_time_ms:10000,max_output_tokens:15000})
]); results.forEach((r,i)=>text(JSON.stringify({i,result:r.status==="fulfilled"?r.value.output:String(r.reason)})));

